"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([["33426"],{32519(e){e.exports=JSON.parse('{"tag":{"label":"docker","permalink":"/docs/tags/docker","allTagsPath":"/docs/tags","count":12,"items":[{"id":"projects/professionnel/bluenav-jumeau-numerique","title":"BlueNav - Jumeau num\xe9rique bateau autonome","description":"Jumeau num\xe9rique du BlueBoat, navire autonome de 12 tonnes destin\xe9 aux voies fluviales : mod\xe8le physique, environnement fluvial et capteurs simul\xe9s sous ROS 2 et Gazebo, pour valider les algorithmes de navigation de BlueNav avant la mise \xe0 l\'eau.","permalink":"/docs/projects/professionnel/bluenav-jumeau-numerique"},{"id":"projects/personnel/body_analysis","title":"Body Analysis","description":"Application de suivi et d\'analyse corporelle (FastAPI, React, PostgreSQL, stockage S3) : phases \xe0 r\xe8gles dynamiques, s\xe9ances de course, de natation et de musculation (montre et Hevy), mensurations, photos recal\xe9es automatiquement, synchronisation par une appli Android et serveur MCP.","permalink":"/docs/projects/personnel/body_analysis"},{"id":"projects/professionnel/crob","title":"C-Rob - Plateforme robotique modulaire sous ROS 2","description":"C-Rob, d\xe9monstrateur RoboCup@Home du CATIE con\xe7u en interne : base mobile holonome sous Zephyr et micro-ROS, PC embarqu\xe9 ROS 2 Jazzy conteneuris\xe9, navigation Nav2, perception IA \xe0 la demande et jumeau num\xe9rique Gazebo. Coordination technique et lead ROS 2 Python.","permalink":"/docs/projects/professionnel/crob"},{"id":"projects/professionnel/cicd","title":"CI/CD - Workflows GitHub Actions mutualis\xe9s","description":"Biblioth\xe8que de workflows GitHub Actions r\xe9utilisables (g\xe9n\xe9rique, Python, ROS, Mbed, Zephyr) appel\xe9e par plusieurs dizaines de d\xe9p\xf4ts du CATIE, du test au d\xe9ploiement Helm ou Compose, avec une documentation v\xe9rifi\xe9e automatiquement contre le code.","permalink":"/docs/projects/professionnel/cicd"},{"id":"projects/personnel/colis-tracker","title":"Colis Tracker","description":"Suivi de colis Colissimo et Chronopost auto-h\xe9berg\xe9, sans cl\xe9 API ni service tiers : interrogation de l\'endpoint de suivi public de La Poste, import automatique des num\xe9ros depuis les mails d\'exp\xe9dition (IMAP), date de livraison pr\xe9vue, notifications ntfy, serveur MCP.","permalink":"/docs/projects/personnel/colis-tracker"},{"id":"projects/personnel/crop","title":"Crop","description":"Carnet de balcon potager auto-h\xe9berg\xe9 : vue 3D isom\xe9trique des emplacements avec ensoleillement calcul\xe9, plan de l\'ann\xe9e, actions dat\xe9es, conseils de plantation, historique annulable, rappels ntfy et serveur MCP qui donne \xe0 Claude les m\xeames op\xe9rations que l\'interface.","permalink":"/docs/projects/personnel/crop"},{"id":"projects/professionnel/github-arc-kubeadm","title":"GitHub ARC - Runners CI/CD auto-h\xe9berg\xe9s sur Kubernetes","description":"Runners GitHub Actions auto-h\xe9berg\xe9s sur le cluster Kubernetes interne du CATIE avec Actions Runner Controller : un runner \xe9ph\xe9m\xe8re par job, jusqu\'\xe0 60 en parall\xe8le, plac\xe9s sur les n\u0153uds \xe0 disque rapide, suivis par Prometheus et acc\xe9l\xe9r\xe9s par des caches partag\xe9s.","permalink":"/docs/projects/professionnel/github-arc-kubeadm"},{"id":"projects/personnel/homelab","title":"HomeLab","description":"Homelab auto-h\xe9berg\xe9 versionn\xe9 en GitOps (Docker Compose, reverse proxy et SSO, CI/CD GitHub Actions, mises \xe0 jour Renovate, secrets chiffr\xe9s en repo, sauvegardes 3-2-1 chiffr\xe9es, supervision et alerting, hub mail, DNS local, documentation g\xe9n\xe9r\xe9e depuis le code).","permalink":"/docs/projects/personnel/homelab"},{"id":"projects/professionnel/minipock","title":"MiniPock - Robot mobile ROS 2","description":"MiniPock, plateforme robotique mobile modulaire du CATIE (versions diff\xe9rentielle et holonome) : pile ROS 2 Jazzy, Nav2, simulation multi-robots sous Gazebo Harmonic, micro-ROS en Wi-Fi, mise \xe0 jour du firmware par ROS 2, planification de missions avec Open-RMF, CI et images Docker.","permalink":"/docs/projects/professionnel/minipock"},{"id":"projects/professionnel/api-cloud","title":"Mise en production cloud d\'une API","description":"Mise en production d\'une API web Python chez un fournisseur de cloud : infrastructure d\xe9crite en Terraform, chart Helm commun \xe0 trois environnements, livraison par GitHub Actions avec un plan d\'infrastructure relu avant d\'\xeatre appliqu\xe9, et ingestion automatique de fichiers d\xe9pos\xe9s dans un stockage objet.","permalink":"/docs/projects/professionnel/api-cloud"},{"id":"projects/personnel/recallarr","title":"Recallarr","description":"Journal personnel de ce qui a \xe9t\xe9 regard\xe9 dans Jellyfin, qui survit au nettoyage de la m\xe9diath\xe8que : synchronisation par webhook et r\xe9conciliation quotidienne, r\xe8gles de note et de favori, suivi des nouvelles saisons et des suites, serveur MCP, interface HTMX.","permalink":"/docs/projects/personnel/recallarr"},{"id":"projects/personnel/ytdl-sub-ui","title":"ytdl-sub-ui","description":"Interface web qui pilote ytdl-sub, le t\xe9l\xe9chargeur de cha\xeenes YouTube vers Jellyfin : recherche et ajout de cha\xeenes sans compte, r\xe9tention, r\xe9glages et suivi des passages, serveur MCP, chaque \xe9criture valid\xe9e par ytdl-sub avant d\'\xeatre mise en place.","permalink":"/docs/projects/personnel/ytdl-sub-ui"}],"unlisted":false}}')}}]);